/**
 * Hand-written type declaration for the adjacent, drizzle-kit-generated
 * `migrations.js` (regenerated by `pnpm db:generate` — see
 * `drizzle.config.ts`). `drizzle-kit generate` only ever (re)writes
 * `migrations.js`, the numbered `.sql` files, and `meta/*`; it never touches
 * this file, so the declaration survives regeneration.
 */

import type { MigrationJournalEntry } from '../migrationPlan';

interface MigrationsBundle {
  readonly journal: {
    readonly version: string;
    readonly dialect: string;
    readonly entries: readonly MigrationJournalEntry[];
  };
  readonly migrations: Readonly<Record<string, string>>;
}

declare const migrations: MigrationsBundle;
export default migrations;
